<style>
:root{--ink:#132238;--muted:#607087;--line:#e4eaf2;--surface:#fff;--soft:#f5f8fc;--brand:#0f5bd7;--brand-dark:#0a43a1;--accent:#f4b41a;--radius:18px;--shadow:0 14px 40px rgba(18,39,70,.08)}*{box-sizing:border-box}html{scroll-behavior:smooth;overflow-x:hidden}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:var(--soft);line-height:1.7}a{color:inherit}button,input,select,textarea{font:inherit}.container{width:min(1180px,90%);margin-inline:auto}.nav{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.96);backdrop-filter:blur(12px);border-bottom:1px solid rgba(228,234,242,.95);min-height:76px;display:flex;align-items:center;justify-content:space-between;padding:12px 5%}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink);font-size:20px;font-weight:850;letter-spacing:-.02em;white-space:nowrap}.brand-mark{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(135deg,var(--brand),#3182f6);color:#fff;font-weight:900;box-shadow:0 8px 18px rgba(15,91,215,.2)}.navlinks{display:flex;align-items:center;gap:7px}.navlinks a{padding:10px 12px;text-decoration:none;color:#52637a;font-size:14px;font-weight:700;border-radius:10px}.navlinks a:hover,.navlinks a.active{color:var(--brand);background:#eef5ff}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 18px;border-radius:11px;text-decoration:none;font-weight:800;border:1px solid transparent;cursor:pointer;background:var(--brand);color:#fff;transition:.18s ease}.btn:hover{background:var(--brand-dark);transform:translateY(-1px)}.btn.secondary{background:#edf4ff;color:var(--brand);border-color:#dbe8ff}.btn.ghost{background:transparent;color:var(--brand);border-color:#d5e1f4}.hero{position:relative;overflow:hidden;padding:100px 0 88px;background:radial-gradient(circle at 85% 20%,rgba(49,130,246,.16),transparent 32%),linear-gradient(135deg,#071d3a 0%,#0c3972 58%,#1163c9 100%);color:#fff}.hero:after{content:"";position:absolute;right:-90px;bottom:-120px;width:360px;height:360px;border:70px solid rgba(255,255,255,.07);border-radius:50%}.hero .eyebrow{color:#bcd7ff}.hero h1{font-size:clamp(42px,6vw,72px);line-height:1.04;letter-spacing:-.045em;max-width:850px;margin:12px 0 22px}.hero p{font-size:19px;color:#dce9fb;max-width:760px}.hero-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}.hero .btn{background:#fff;color:#0b4eae}.hero .btn.secondary{background:rgba(255,255,255,.1);color:#fff;border-color:rgba(255,255,255,.25)}.eyebrow{font-size:12px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;color:var(--brand);margin:0}.section{padding:72px 0}.section.alt{background:#fff}.section-head{display:flex;justify-content:space-between;align-items:end;gap:25px;margin-bottom:28px}.section-head h2{margin:4px 0 0;font-size:clamp(26px,3vw,38px);line-height:1.15;letter-spacing:-.025em}.section-head p{margin:7px 0 0;color:var(--muted);max-width:650px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px}.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:25px;box-shadow:var(--shadow)}.card h3{margin:0 0 8px;line-height:1.3}.card p:last-child{margin-bottom:0}.card-link{text-decoration:none;display:block;transition:.18s ease}.card-link:hover{transform:translateY(-3px);border-color:#c9dcfb}.icon{width:46px;height:46px;border-radius:13px;background:#eef5ff;color:var(--brand);display:grid;place-items:center;font-weight:900;margin-bottom:18px}.stat-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:#dfe7f1;border:1px solid #dfe7f1;border-radius:16px;overflow:hidden}.stat-strip>div{background:#fff;padding:22px}.stat-strip strong{display:block;font-size:28px}.muted{color:var(--muted)}.badge{display:inline-flex;align-items:center;padding:5px 9px;border-radius:999px;background:#edf5ff;color:var(--brand);font-size:12px;font-weight:850}.empty{border:1px dashed #cdd8e6;border-radius:16px;padding:28px;text-align:center;color:var(--muted);background:#fff}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.field{display:flex;flex-direction:column;gap:7px;min-width:0}.field.full{grid-column:1/-1}.field label{font-weight:800;font-size:14px}.field input,.field select,.field textarea{width:100%;padding:13px 14px;border:1px solid #d4deea;border-radius:11px;background:#fff;color:var(--ink);outline:0}.field input:focus,.field select:focus,.field textarea:focus{border-color:#6fa4ef;box-shadow:0 0 0 4px rgba(15,91,215,.08)}.field textarea{min-height:130px;resize:vertical}.alert{padding:14px 16px;border-radius:11px;margin-bottom:18px}.success{background:#e9f8ef;color:#176b3a}.error{background:#fff0f0;color:#a51d2d}.errors{margin:0 0 18px;padding:15px 18px;background:#fff0f0;color:#a51d2d;border-radius:11px}.footer{background:#091a30;color:#dce8f6;padding:58px 0 22px;margin-top:0}.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1.3fr;gap:35px}.footer h3,.footer h4{color:#fff;margin-top:0}.footer p{color:#aebed1}.footer a{color:#cbd8e7;text-decoration:none}.footer a:hover{color:#fff}.footer-bottom{border-top:1px solid rgba(255,255,255,.1);margin-top:35px;padding-top:18px;display:flex;justify-content:space-between;gap:20px;font-size:13px;color:#91a4bb}.page-hero{padding:65px 0 55px;background:linear-gradient(135deg,#eef5ff,#fff);border-bottom:1px solid #e0e8f2}.page-hero h1{font-size:clamp(34px,5vw,54px);line-height:1.08;letter-spacing:-.04em;margin:8px 0 12px}.page-hero p{max-width:700px;color:var(--muted);font-size:17px}.split{display:grid;grid-template-columns:1.2fr .8fr;gap:24px;align-items:start}.notice{border-left:4px solid var(--accent);background:#fff9e8;padding:17px 20px;border-radius:0 12px 12px 0}.table-wrap{overflow-x:auto;max-width:100%;background:#fff;border:1px solid var(--line);border-radius:14px}.table{width:100%;border-collapse:collapse;min-width:620px}.table th,.table td{text-align:left;padding:13px 15px;border-bottom:1px solid #edf0f5}.table th{background:#f8f9fc;font-size:13px;text-transform:uppercase;letter-spacing:.04em}.admin-shell{min-height:100vh;background:#f5f7fb}.admin-top{background:#091a30;color:#fff;padding:18px 4%;display:flex;justify-content:space-between;align-items:center;gap:15px}.admin-layout{display:grid;grid-template-columns:240px minmax(0,1fr);min-height:calc(100vh - 66px)}.sidebar{background:#fff;border-right:1px solid #e4e9f2;padding:24px 15px}.sidebar a{display:block;padding:11px 13px;border-radius:9px;text-decoration:none;color:#526078;margin-bottom:5px}.sidebar a.active,.sidebar a:hover{background:#edf3ff;color:#1769e0}.admin-main{padding:30px 4%;min-width:0}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.stat{background:#fff;border:1px solid #e4e9f2;border-radius:14px;padding:22px;min-width:0}.stat strong{font-size:30px;display:block;overflow-wrap:anywhere}@media(max-width:1000px){.footer-grid{grid-template-columns:1fr 1fr}.stat-strip{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.nav{padding:12px 5%;align-items:flex-start}.navlinks{gap:3px;flex-wrap:wrap;justify-content:flex-end}.navlinks a{padding:8px 9px;font-size:13px}.navlinks .btn{padding:9px 12px}.hero{padding:72px 0 65px}.section{padding:52px 0}.form-grid,.split,.footer-grid,.admin-layout{grid-template-columns:1fr}.section-head{display:block}.stat-grid{grid-template-columns:repeat(2,1fr);gap:10px}.admin-top{padding:14px 5%;align-items:flex-start;flex-wrap:wrap}.admin-main{padding:22px 5%}.sidebar{border-right:0;border-bottom:1px solid #e4e9f2;padding:14px}.sidebar a{display:inline-block;margin:0 4px 5px 0}.hero-actions{margin-top:24px}}@media(max-width:480px){.brand{font-size:17px}.brand-mark{width:36px;height:36px}.nav{display:block}.navlinks{margin-top:9px;justify-content:flex-start}.hero h1{font-size:40px}.hero p{font-size:17px}.stat-strip{grid-template-columns:1fr}.stat-grid{grid-template-columns:1fr}.btn{padding:11px 14px}}
</style>
